#!/usr/bin/env python3
"""Render the website from its pinned, downloadable conformance record."""
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
data = json.loads((ROOT / 'data/conformance.json').read_text())
baseline = data['test262']
ts = data['typescript']
diff = data['differential']
groups = data['groups']
passed = sum(v['passed'] for v in groups.values())
failed = sum(v['failed'] for v in groups.values())
source = f"https://github.com/sunfall-labs/kiln/blob/{data['source_commit']}/"

def table(headers, rows):
    return '<div class="table-scroll" tabindex="0" role="region" aria-label="Conformance results"><table><thead><tr>' + ''.join(f'<th scope="col">{html.escape(h)}</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr><th scope="row">' + html.escape(str(row[0])) + '</th>' + ''.join(f'<td>{html.escape(str(v))}</td>' for v in row[1:]) + '</tr>' for row in rows) + '</tbody></table></div>'

def chart(name, title, rows, total, normalized=False):
    height = 70 + 48 * len(rows)
    body = [f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 560 {height}" role="img" aria-labelledby="{name}-title {name}-desc">',f'<title id="{name}-title">{title}</title>',f'<desc id="{name}-desc">' + html.escape('; '.join(f'{label}: {p:,} of {p+f:,} cases' for label,p,f in rows)) + '. Zero baseline. Exact counts are available in the accompanying table.</desc>']
    for i,(label,p,f) in enumerate(rows):
        y=18+i*48; ratio=p/(p+f) if normalized else p/total
        body += [f'<text x="0" y="{y+16}" font-family="sans-serif" font-size="13" fill="#292d24">{label}</text>',f'<rect x="160" y="{y}" width="260" height="23" fill="#ebece3"/>',f'<rect x="160" y="{y}" width="{260*ratio:.4f}" height="23" fill="#b6462b"/>',f'<text x="550" y="{y+16}" text-anchor="end" font-family="monospace" font-size="13" fill="#292d24">{ratio*100:.2f}%</text>']
    y=height-31
    body += [f'<path d="M160 {y-9}H420" stroke="#a9ad9f"/>',f'<text x="160" y="{y+10}" font-family="monospace" font-size="11" fill="#73796b">0%</text>',f'<text x="420" y="{y+10}" text-anchor="end" font-family="monospace" font-size="11" fill="#73796b">100%</text>','</svg>']
    (ROOT/'assets/charts'/f'{name}.svg').write_text('\n'.join(body)+'\n')

labels={'language':'Language','built-ins':'Built-ins','intl402':'Intl','annexB':'Annex B','staging':'Staging'}
chart('conformance','Test262 recorded passes by category',[(labels[k],groups[k]['passed'],groups[k]['failed']) for k in labels],0,True)
levels=[('All','Exact output'),('Spans','Diagnostic spans'),('Words','Message words'),('Codes','Error codes'),('Differs','Differs'),('Broken','Broken')]
chart('typescript','TypeScript conformance match levels',[(label,ts['levels'][key],ts['tests']-ts['levels'][key]) for key,label in levels],ts['tests'])
category_table=table(['Category','Passing','Failing','Chunks'],[(labels[k],f"{groups[k]['passed']:,}",f"{groups[k]['failed']:,}",groups[k]['chunks']) for k in labels])
ts_table=table(['Highest matching level','Cases','Share'],[(label,f"{ts['levels'][key]:,}",f"{ts['levels'][key]/ts['tests']*100:.2f}%") for key,label in levels])
summary=f'''<div class="conformance-stats"><article><strong>{ts['levels']['All']:,} / {ts['tests']:,}</strong><span>TypeScript cases match reference output exactly</span></article><article><strong>{diff['matching']:,} / {diff['compared']:,}</strong><span>Differential cases match tsc {diff['tsc']}</span></article><article><strong>{passed:,}</strong><span>Recorded passing Test262 variants · {len(baseline['chunks'])} chunks</span></article></div>'''
page=ROOT/'index.html'; text=page.read_text()
for name,fragment in {'conformance-summary':summary,'conformance-table':category_table,'typescript-table':ts_table}.items():
    start,end=f'<!-- generated:{name} -->',f'<!-- /generated:{name} -->'
    before,rest=text.split(start,1); _,after=rest.split(end,1)
    text=before+start+'\n'+fragment+'\n'+end+after
page.write_text(text)

def code(filename):
    return f'<div class="code-card"><div class="code-heading"><span>{filename}</span><a download href="../examples/{filename}">Download ↓</a></div><pre><code>'+html.escape((ROOT/'examples'/filename).read_text().rstrip())+'</code></pre></div>'

def document(path,title,intro,body):
    markup=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{html.escape(intro,quote=True)}"><title>{title} — kiln reference</title><link rel="icon" href="../mark.svg"><link rel="stylesheet" href="../style.css"></head><body><a class="skip" href="#main">Skip to content</a><div class="page"><header><a class="brand" href="../"><img src="../mark.svg" width="30" height="34" alt=""><span>kiln.</span></a><nav aria-label="Reference navigation"><a href="./">Reference</a><a href="../#start">Install</a><a href="https://github.com/sunfall-labs/kiln">Source</a></nav></header><main id="main" class="reference"><div class="reference-heading"><span class="eyebrow">KILN / TECHNICAL REFERENCE</span><h1>{title}</h1><p>{intro}</p></div>{body}</main><footer><a href="../">← kiln home</a><a href="./">All reference pages</a><span>v0.1.0 · pinned source data</span></footer></div></body></html>'''
    (ROOT/'reference'/path).write_text(markup+'\n')

links='<div class="reference-links"><a href="type-checking.html"><strong>TypeScript checking</strong><span>Commands, TS7 evidence and compiler architecture →</span></a><a href="conformance.html"><strong>Conformance evidence</strong><span>Every chunk, match levels and reproducible baselines →</span></a><a href="concurrency.html"><strong>Concurrency and ownership</strong><span>Typed actors, parallel collections and shared graphs →</span></a></div>'
document('index.html','TypeScript, down to the details.','Reference material for the compiler, compatibility evidence and runtime extensions.',links)
checker=f'''<section><h2>Check source before you compile.</h2><pre><code>kiln check hello.ts
kiln check --explain-parallel parallel.ts
kiln run hello.ts
kiln build hello.ts
./hello</code></pre><p><code>kiln check</code> reports TypeScript source diagnostics. It reads project tsconfig options, including JSONC and extends, and package declaration targets. With no tsconfig it uses strict checks, esnext and module: preserve. Node and kiln declarations are embedded, including typed actors and parallel collection methods.</p>{code('hello.ts')}<p>The checker is integrated with kiln’s parser and source snapshots. Its binding, inference, narrowing and type-relation algorithms are ported from Bun’s source checker, including the Microsoft checker and binder ports. It is a source checker, not just type stripping.</p><h2>What “TypeScript 7” means here.</h2><p>The standard declaration libraries are pinned TypeScript 7.0.2 inputs. Two separate reference suites measure diagnostics against TypeScript’s own tests and <code>tsc</code> 7.0.2.</p>{summary}{ts_table}<p>“Exact output” means the complete reference diagnostic output matches byte for byte. Partial levels measure spans, words or error codes; they do not imply an exact match. The differential suite matches {diff['matching']:,} of {diff['compared']:,} cases; the other {diff['compared']-diff['matching']:,} differ. These corpora measure tested cases, not full drop-in compatibility with every TypeScript project.</p><h2>Types inform guarded optimization.</h2><img class="diagram-svg reference-diagram" src="../assets/diagrams/checker.svg" width="800" height="320" alt="Authored TypeScript goes through one parser. Source checking supplies diagnostics and type contracts, while executable lowering supplies the program. Guarded native specialization combines them with a fallback."><p>Authored source coordinates are retained for diagnostics. Complete checker results can supply compiler contracts; incomplete adaptation or exhausted checker budgets disable optimization hints. An annotation, <code>any</code>, or unchecked assertion is not a runtime proof. Specialized native paths keep guards and generic fallbacks.</p><h2>Reproduce the compatibility checks.</h2><pre><code>mise run ts-conformance
mise run tsc-differential</code></pre><p>These contributor commands fetch pinned reference inputs and fail when a recorded case regresses. The checker integrates project configuration and module snapshots; adaptation gaps and integration limits remain explicit.</p><p class="evidence-links"><a href="{source}crates/compile/kiln-type-checker/README.md">Checker architecture and limits</a><a href="{source}conformance/ts-conformance-baseline.json">TypeScript conformance baseline</a><a href="{source}conformance/tsc-differential-baseline.json">tsc differential baseline</a></p></section>'''
document('type-checking.html','Check TypeScript. Compile native.','Source checking with pinned TypeScript 7.0.2 libraries and compatibility measured against reference diagnostics.',checker)
chunks=table(['Chunk','Passing','Failing'],[(k,f"{v['passed']:,}",f"{v['failed']:,}") for k,v in baseline['chunks'].items()])
conformance=f'''<section><h2>Two kinds of compatibility.</h2><p>TypeScript checking asks whether source diagnostics match the reference checker. Test262 asks whether JavaScript language behavior matches ECMAScript. A result in one suite is not a result in the other.</p>{summary}<h2>TypeScript diagnostic fidelity</h2><img class="diagram-svg reference-chart" src="../assets/charts/typescript.svg" width="560" height="358" alt="TypeScript conformance match levels with exact counts in the table below.">{ts_table}<h2>Runtime behavior, category by category</h2><img class="diagram-svg reference-chart" src="../assets/charts/conformance.svg" width="560" height="310" alt="Test262 recorded passing proportions by category with exact counts in the table below.">{category_table}<p>The committed Test262 baseline records {passed:,} passing and {failed:,} failing variants across {len(baseline['chunks'])} chunks. Its stored pass/fail denominator is {passed+failed:,}; unsupported and skipped outcomes are not represented here. The corpus pin is <code>{baseline['test262_commit']}</code>.</p><h2>How to read this evidence</h2><p>This is the committed v0.1.0 reference, not a fresh complete-corpus run. A regression gate compares individual chunks so gains in one area cannot hide losses in another. Routine Test262 runs defer the reviewed extended cases; full runs include them. Test case variants are not counts of language features or supported npm packages.</p><p>Native probes compare execution modes, while the thirdparty runner compares real bundle outputs with Node. A language baseline, engine parity check and library check each answer a different question.</p><pre><code>mise run gate        # routine correctness and parity
mise run gate-full   # also extended cases and postcss performance
mise run test262-full</code></pre><h2>Every recorded Test262 chunk</h2>{chunks}<p class="evidence-links"><a href="../data/conformance.json" download>Download all website source data</a><a href="{source}conformance/test262-baseline.json">Original Test262 baseline</a><a href="{source}AGENTS.md">Reproduction and corpus runners</a><a href="../assets/charts/conformance.svg" download>Download chart SVG</a></p></section>'''
document('conformance.html','Evidence you can inspect.','Pinned TypeScript checker and ECMAScript runtime baselines, with counts, source links and every Test262 chunk.',conformance)
concurrency=f'''<section><p>Save the downloaded examples together with <a href="../examples/package.json" download>package.json</a>, which declares the project as ESM. This module setting is needed for these native TypeScript actor examples in v0.1.0.</p><h2>Parallel callbacks with a checked fallback.</h2>{code('parallel.ts')}<pre><code>kiln check --explain-parallel parallel.ts
kiln run parallel.ts
kiln run --native parallel.ts</code></pre><p>The compiler proves which callbacks have no observable side effects. Native execution can distribute substantial independent work over scheduler lanes. Getters, I/O, random state, clocks and unproven calls can keep execution sequential. A runtime guard or a small workload can also keep a proven call inline. This tiny example demonstrates semantics, not a measured speedup.</p><img class="diagram-svg reference-diagram" src="../assets/diagrams/parallel.svg" width="360" height="220" alt="Independent collection chunks run on scheduler lanes and return ordered results."><h2>Typed calls to isolated state.</h2>{code('counter.ts')}{code('main.ts')}<p><code>spawnActor&lt;Counter&gt;</code> returns a typed reference. Method names, arguments and awaited results follow Counter’s public methods. Actors own isolated realm state; a bounded mailbox limits accepted work. Native actors share a bounded scheduler rather than requiring one OS thread per actor. An asynchronous method releases its lane between turns; another call can progress when it awaits.</p><pre><code>kiln check main.ts
kiln --node run main.ts
kiln --node run --native main.ts</code></pre><img class="diagram-svg reference-diagram" src="../assets/diagrams/actors.svg" width="360" height="100" alt="Typed asynchronous calls enter a bounded actor mailbox and execute in the actor’s realm."><p>For this actor, <code>owner.ref.call('increment', ['three'])</code> produces TS2322 and <code>owner.ref.call('missing', [])</code> produces TS2345 in <code>kiln check</code>.</p><h2>Share an immutable object graph.</h2>{code('shared-main.ts')}<p><code>share</code> creates an immutable snapshot. The source remains independent. Subsequent native sends retain the graph rather than cloning its fields; the Shared type also makes nested data readonly in TypeScript.</p><img class="diagram-svg reference-diagram" src="../assets/diagrams/share.svg" width="360" height="105" alt="Two realms read a single shared immutable graph."><h2>Choose ownership deliberately.</h2><p>Plain messages clone. <code>transfer(buffer)</code> moves an ArrayBuffer when a call is accepted and detaches the sender. <code>prepareTransfer(value)</code> copies a source graph into private storage, then moves that snapshot on a native handoff. <code>isolate(factory)</code> can move certified native heap chunks without copying when exclusive ownership is proved. The interpreter preserves move semantics by encoding and reconstructing the verified graph. Unsupported graphs and ownership failures raise DataCloneError.</p><p>These are kiln-specific APIs that reduce the application machinery around workers and serialization. Other runtimes have workers and transfer mechanisms too; these diagrams describe kiln’s design, not benchmark wins. Actor bootstrap has memory and latency costs, and application capacity needs measurement.</p><p class="evidence-links"><a href="{source}docs/parallel-builtins.md">Parallel proofs, tiers and reduction order</a><a href="{source}docs/actors.md">Actor lifecycle, transfer and capacity</a><a href="{source}packages/kiln-types/actors.d.ts">Actor types</a></p></section>'''
document('concurrency.html','Types, cores and ownership.','Runnable TypeScript examples for kiln’s parallel methods, typed actor calls and shared immutable graphs.',concurrency)
print('Rendered conformance charts, tables and four reference pages from pinned data.')
